import React from 'react';
import {
  AppShell,
  Container,
  Group,
  Text,
  Button,
  Badge,
  ActionIcon,
  Menu,
  Avatar,
  Box,
  TextInput,
} from '@mantine/core';
import { Cart as BsCart, Shop as BsShop, FilePersonFill as FilePersonFill, Speedometer2 as BsSpeedometer2, BoxArrowInRight as BsBoxArrowInRight, Search as BsSearch } from 'react-bootstrap-icons';
import { NavLink, Outlet, useNavigate, useLocation, useSearchParams } from 'react-router-dom';
import { useCart } from '../hooks/useCart';
import { useAuth } from '../hooks/useAuth';

export const AppLayout: React.FC = () => {
  const { totalItems } = useCart();
  const { user, isAuthenticated, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [searchParams, setSearchParams] = useSearchParams();

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const val = event.target.value;

    // Se não está no catálogo nem no carrinho, redireciona para o catálogo já buscando
    if (location.pathname !== '/' && location.pathname !== '/carrinho') {
      if (val) {
        navigate(`/?q=${encodeURIComponent(val)}`);
      } else {
        navigate('/');
      }
      return;
    }

    if (val) {
      searchParams.set('q', val);
    } else {
      searchParams.delete('q');
    }
    setSearchParams(searchParams, { replace: true });
  };

  return (
    <AppShell
      header={{ height: { base: 60, md: 70 } }}
      footer={{ height: { base: 40, md: 60 } }}
      padding="0"
      styles={{
        main: {
          backgroundColor: '#f8f9fa',
          height: '100vh',
          overflow: 'hidden',
          display: 'flex',
          flexDirection: 'column',
        },
      }}
    >
      <AppShell.Header>
        <Container fluid px="md" h="100%">
          <Group justify="space-between" h="100%" wrap="nowrap" gap="xs">
            {/* Logo */}
            <Group
              wrap="nowrap"
              gap="xs"
              style={{ cursor: 'pointer', textDecoration: 'none' }}
              onClick={() => navigate('/')}
            >
              <ActionIcon variant="filled" color="indigo" size="lg" radius="md">
                <BsShop size={22} />
              </ActionIcon>
              <Box visibleFrom="xs">
                <Text fw={800} size="lg" c="indigo.8" lh={1.1} component="span">
                  Mantine Store
                </Text>
              </Box>
            </Group>

            {/* Global Search Bar */}
            <TextInput
              placeholder={location.pathname === '/carrinho' ? "Buscar no carrinho..." : "Buscar produtos..."}
              leftSection={<BsSearch size={16} />}
              value={searchParams.get('q') || ''}
              onChange={handleSearchChange}
              style={{ flex: 1, maxWidth: 400 }}
              size="sm"
              radius="xl"
            />

            {/* Navigation links */}
            <Group gap="sm" wrap="nowrap">

              {isAuthenticated && (
                <NavLink
                  to="/carrinho"
                  style={({ isActive }) => ({
                    textDecoration: 'none',
                    color: isActive ? 'var(--mantine-primary-color-filled)' : '#495057',
                    fontWeight: isActive ? 700 : 500,
                    padding: '8px 14px',
                    borderRadius: '16px',

                    display: 'flex',
                    alignItems: 'center',
                    gap: '6px',
                    transition: 'all 0.2s',
                  })}
                >
                  <BsCart size={18} />
                  <Text component="span" visibleFrom="md">Carrinho</Text>
                  {totalItems > 0 && (
                    <Badge color="red" size="sm" circle>
                      {totalItems}
                    </Badge>
                  )}
                </NavLink>
              )}

            </Group>

            {/* User auth action */}
            <Group gap="xs" wrap="nowrap">
              {isAuthenticated && user ? (
                <Menu shadow="md" width={200} position="bottom-end">
                  <Menu.Target>
                    <Button
                      variant="transparent"
                      color="gray"
                      leftSection={
                        <Avatar
                          alt={user.username}
                          radius="xl"
                          size="sm"
                          color="indigo"
                        >
                          {user.username.slice(0, 2).toUpperCase()}
                        </Avatar>
                      }
                    >
                      <Text size="sm" fw={600} visibleFrom="md">
                        {user.firstName ? `${user.firstName}` : user.username}
                      </Text>
                    </Button>

                  </Menu.Target>

                  <Menu.Dropdown>
                    <Menu.Label>Conectado como {user.username}</Menu.Label>
                    <Menu.Item
                      leftSection={<BsSpeedometer2 size={14} />}
                      onClick={() => navigate('/admin')}
                    >
                      Perfil
                    </Menu.Item>
                    <Menu.Divider />
                    <Menu.Item
                      color="red"
                      leftSection={<FilePersonFill size={14} />}
                      onClick={handleLogout}
                    >
                      Sair da Conta
                    </Menu.Item>
                  </Menu.Dropdown>
                </Menu>
              ) : (
                <>
                  <ActionIcon
                    variant="filled"
                    color="indigo"
                    size="lg"
                    radius="md"
                    onClick={() => navigate('/login')}
                    hiddenFrom="md"
                    aria-label="Entrar"
                  >
                    <FilePersonFill size={18} />
                  </ActionIcon>

                  <Button
                    variant="filled"
                    color="indigo"
                    size="sm"
                    leftSection={<BsBoxArrowInRight size={16} />}
                    onClick={() => navigate('/login')}
                    visibleFrom="md"
                  >
                    Entrar
                  </Button>
                </>
              )}
            </Group>
          </Group>
        </Container>
      </AppShell.Header>

      <AppShell.Main>
        <Container fluid px={{ base: 'xs', sm: 'md', lg: 'lg' }} py="xs" style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
          <Outlet />
        </Container>
      </AppShell.Main>

      <AppShell.Footer>
        <Container fluid px="md" h="100%">
          <Group justify="space-between" align="center" h="100%" wrap="nowrap">
            <Text size="xs" c="dimmed" visibleFrom="md">
              © {new Date().getFullYear()} UTFPR — Especialização em Engenharia de Software.
            </Text>
            <Group gap="md" wrap="nowrap">
              <Text size="xs" c="dimmed" visibleFrom="md">
                Dados fornecidos por DummyJSON API
              </Text>
              <Text size="xs" fw={600} c="indigo">
                React + Mantine + CI/CD
              </Text>
            </Group>
          </Group>
        </Container>
      </AppShell.Footer>
    </AppShell>
  );
};

export default AppLayout;
